import heapq


def temporal(policy):
    def solve(data):
        required = data.get("required", [])
        bits = {name: 1 << i for i, name in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bits.get(source, 0)
        coupons = data["coupons"]
        # State is (node, remaining coupons, visited mask); retain its earliest time.
        start = (source, coupons, initial_mask)
        best = {start: data["start"]}
        queue = [(data["start"], source, coupons, initial_mask)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, left, mask = heapq.heappop(queue)
            state = (node, left, mask)
            if best.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (policy != "exact" or left == 0)):
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], left)]
                if left:
                    minimum = 1 if policy in ("at_most_1", "exact_1") else 2
                    duration = max(minimum, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, left - 1))
                for duration, new_left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    new_mask = mask | bits.get(nxt, 0)
                    next_state = (nxt, new_left, new_mask)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, new_left, new_mask))
        return {"arrival": None}
    return solve


def ledger(data):
    events = data["events"]
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(events):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))

    def rounded(n, d):
        q, r = divmod(n, d)
        if data["rounding"] == "half_up" and 2 * r >= d:
            q += 1
        return q

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    choices = [[-1] + sorted(row["version"] for row in packages[name])
               for name in names]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    for vector in itertools.product(*choices):
        installed = dict(zip(names, vector))
        if any(installed[name] < 0 or not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(version >= 0 and version in blocked.get(name, [])
               for name, version in installed.items()):
            continue
        if any(installed.get(name, -1) != version for name, version in pins.items()
               if installed.get(name, -1) >= 0):
            continue
        rows_by_version = {name: {row["version"]: row for row in rows}
                           for name, rows in packages.items()}
        graph = {name: [] for name in names}
        valid = True
        for name, version in installed.items():
            if version < 0:
                continue
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = installed.get(target, -1)
                if target_version < dep["min"] or target_version > dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = [name for name in roots]
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if installed.get(name, -1) >= 0:
                stack.extend(graph[name])
        if any((installed[name] >= 0) != (name in reachable) for name in names):
            continue

        visiting, visited = set(), set()
        def acyclic(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in graph[name]):
                return False
            visiting.remove(name)
            visited.add(name)
            return True
        if not all(acyclic(name) for name in names if installed[name] >= 0):
            continue
        return {"versions": {name: version for name, version in installed.items()
                             if version >= 0}}
    return {"error": "unsatisfiable"}


def intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    best_value = None
    best_ids = None
    for selected in itertools.combinations(
            [job for job in jobs if job["id"] not in blocked], k):
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in data.get("quotas", {}).items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


